    if 'win' in l and 'sum' in l and ('result' in l or 'scale' in l or 'correct' in l):
        if 'abs' in l or 'sum()' in l:
            pass
# Let's just show a slice around where they mention 'scale' and 'win'
for i,l in enumerate(lines):
    if 'Bendat' in l or 'win.sum' in l or 'win*win' in l or 'scaling_factor' in l:
        start=max(0,i-5); end=min(len(lines), i+10)
        print('--- around line', i+1,'---')
        print('\n'.join(f"{j+1:4d}: {lines[j]}" for j in range(start,end)))
